let activeSets=null;
export function setActiveSets(sets){activeSets=sets;}
export function matchTags(cards){if(cards.length!==3||cards.some(c=>!c)||new Set(cards.map(c=>c.id)).size!==3)return [];return activeSets===null?sharedTags(cards):(activeSets.find(s=>setKey(s.ids)===setKey(cards.map(c=>c.id)))?.tags||[]);}
export function shuffle(items,random=Math.random){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
export function sharedTags(cards){if(cards.length!==3||cards.some(c=>!c)||new Set(cards.map(c=>c.id)).size!==3)return [];return cards[0].visual.filter(t=>cards.every(c=>c.visual.includes(t)));}
export function findTrio(cards,excludedTag=null){if(activeSets!==null){const byId=new Map(cards.map(c=>[c.id,c]));const order=new Map(cards.map((c,i)=>[c.id,i]));const rank=s=>s.ids.reduce((sum,id)=>sum+order.get(id),0);const matches=activeSets.filter(s=>s.ids.every(id=>byId.has(id))).sort((a,b)=>rank(a)-rank(b));const s=matches.find(s=>!s.tags.includes(excludedTag))||matches[0];return s?{cards:s.ids.map(id=>byId.get(id)),tag:s.tags[0]}:null;}const buckets=new Map();for(const c of cards)for(const tag of c.visual){if(tag===excludedTag)continue;const group=buckets.get(tag)||[];group.push(c);buckets.set(tag,group);if(group.length===3)return {cards:group,tag};}return null;}
export function deal(pool,random=Math.random,preferred=[]){const mixed=shuffle(pool,random),preferredCards=preferred.map(id=>mixed.find(c=>c.id===id)),first=(matchTags(preferredCards).length?{cards:preferredCards,tag:matchTags(preferredCards)[0]}:null)||findTrio(mixed.filter(c=>c.channels?.includes('Unexpected')))||findTrio(mixed);if(!first)return {board:mixed.slice(0,12),remaining:mixed.slice(12),playable:false};const seed=[...first.cards],ids=new Set(seed.map(c=>c.id));const second=findTrio(mixed.filter(c=>!ids.has(c.id)),first.tag);if(second)for(const c of second.cards){seed.push(c);ids.add(c.id);}const rest=mixed.filter(c=>!ids.has(c.id)),take=Math.max(0,12-seed.length),needed=Math.max(0,8-seed.filter(c=>c.channels?.includes('Unexpected')).length),priority=rest.filter(c=>c.channels?.includes('Unexpected')).slice(0,Math.min(needed,take)),priorityIds=new Set(priority.map(c=>c.id)),ordered=[...priority,...rest.filter(c=>!priorityIds.has(c.id))];return {board:shuffle([...seed,...ordered.slice(0,take)],random),remaining:shuffle(ordered.slice(take),random),playable:true};}
export function advance(board,remaining,selected){if(!matchTags(selected).length||!selected.every(c=>board.some(b=>b.id===c.id)))throw new Error('Invalid trio');const ids=new Set(selected.map(c=>c.id)),kept=board.filter(c=>!ids.has(c.id)),take=Math.min(12-kept.length,remaining.length),next=[...kept,...remaining.slice(0,take)],rest=remaining.slice(take);if(findTrio(next))return {board:next,remaining:rest,playable:true,reshuffled:false};const d=deal([...next,...rest]);return {...d,reshuffled:d.playable};}
